"""Build submission.zip for config C2 = A + localize skill with --ppr (Gemma 4 Developer Agent).

C2 = config A (public walkthrough v2, credited) + the `localize` skill run with --ppr (BM25-seeded
PageRank file re-rank over a source call-graph) + test-node filter. Only difference from C is the --ppr
flag in the Step-0 prompt. Writes /kaggle/working/submission.zip and validates it. Submit THIS notebook.
"""
import json, os, re, zipfile, shutil
from pathlib import Path
import yaml

FILES = {
 "agent.yaml": "name: swe_coder\nmodel: gemma-4-31b-it-qat-w4a16-ct\ndescription: Fixes one repository issue with a small, verified source patch.\ninstruction: !include prompts/system.md\ntools:\n  - run_command\n  - read_file\n  - edit_file\n  - write_file\n  - get_status\n  - submit_patch\n  - get_code_neighbors\n  - search_similar_code\n  - get_code_subgraph\n  - agent_tool:\n      config_path: sub_agents/code_analyzer.yaml\n      skip_summarization: true\nskills:\n  - skills/localize\ngenerate_content_config: !include configs/sampling.yaml\n",
 "eval_config.yaml": "# Per-task cap (safe for the shared 12h wall-clock incl. setup). The agent self-terminates via\n# submit_patch well before this; a 129-task run finishes in well under 12h (walkthrough: ~80 min).\nevaluation:\n  timeout_seconds: 120\n  max_time_minutes: 4\n  max_turns: 80\n",
 "configs/sampling.yaml": "temperature: 0.2\ntop_p: 0.95\ntop_k: 40\nmax_output_tokens: 8192\nseed: 42\nthinking_config:\n  thinking_budget: 4096\n  include_thoughts: false\n",
 "prompts/system.md": "## Step 0 \u2014 Localize first (localize skill)\nBefore exploring, find likely edit sites: run the `localize` skill script with `run_skill_script`\n(skill `localize`, script `scripts/localize.py`), passing `--root /workspace --k 10 --ppr` and the issue text (the --ppr flag re-ranks files by BM25-seeded PageRank over a source call-graph).\nIf run_skill_script is unavailable, run it with run_command: `python3 skills/localize/scripts/localize.py --root /workspace --k 10 --ppr \"<issue>\"`.\nIt prints a ranked shortlist of files and `file:line-range symbol`. Read the top 1-3 with read_file,\nthen continue the workflow below. Do not edit tests.\n\nYou are an autonomous software engineer fixing one issue in the Python repository at /workspace. No one will answer questions. Keep working with your tools until the fix is in place, then call `submit_patch()`.\n\n## How you are graded\n- Hidden tests run on your changes in a fresh checkout. Only source changes in the working tree count, and a careful best-effort fix beats no patch.\n- If time runs out, the working tree is graded as it is, so never revert a plausible fix.\n- Test files used by the hidden tests are reset before grading, so editing tests never helps. Never edit tests, `pytest.ini` or `conftest.py`.\n\n## Environment\n- Offline, with dependencies installed. Do not install packages.\n- /workspace is a git repository at the base commit.\n- Available: git, grep, find, sed, awk, python3. Not available: rg (ripgrep), tree.\n- Commands time out after 300 seconds and output is cut at 5,000 characters. `read_file` returns at most 150 lines, so read focused ranges.\n- `get_status()` and `submit_patch()` are free.\n\n## Workflow\n1. Understand. Work out the expected and the actual behaviour. Some issues are pull-request descriptions: skip checklists and template text, keep the substance. Note exact names, messages and values.\n2. Localize. Call `code_analyzer` with the issue text; it replies with LOCATION, ROOT CAUSE and FIX PLAN. Confirm by reading those lines. If it is unsure or wrong, search yourself: `git grep -n \"<identifier>\" -- '*.py' | head -30`.\n3. Reproduce. Write a minimal script to /tmp/repro.py that shows the problem, and run it.\n4. Fix. Edit with `edit_file`: copy `old_string` exactly from the file, including indentation, and keep it short but unique. Fix the root cause, handle the edge cases the issue names, and keep public signatures unchanged. Documentation examples under `docs_src/` count as source when the issue concerns them.\n5. Verify. After each edit run `python3 -m py_compile <file>` and rerun /tmp/repro.py, then run the targeted tests described below.\n6. Submit. Check `git status --short` and `git diff`, remove anything unintended, then call `submit_patch()` as your last tool call and reply with one line on what changed.\n\n## Tests\n- Run only the test file or test that exercises your change: `python3 -m pytest tests/test_x.py -q -x -k <name>`, or `python3 -m unittest tests.test_x`. Find test files with `git ls-files | grep test_<name>`.\n- Never run bare `pytest`, `pytest .` or `python3 -m unittest discover`. A whole suite can take minutes and use up your time.\n- Existing tests may already fail for reasons unrelated to the issue, such as missing fixtures, no network access or import errors. Ignore those failures: do not fix them, stub them or change test code. Judge your fix by the tests that exercise it.\n\n## Code-graph tools\n- `get_code_neighbors` and `get_code_subgraph` show synchronous call relationships only: the graph has only \"calls\" edges and no async functions.\n- `search_similar_code` takes a symbol name such as `APIKeyHeader`, not a sentence, and its ranking is imprecise. Confirm every hit by reading the code.\n- If a graph tool returns an error, stop using it. For async code and everything else, use `git grep` and `read_file`.\n\n## Pace\n- Call `get_status()` every 8 or so tool calls. When a quarter of the time remains, stop exploring and go straight to fix, verify and submit.\n- Keep outputs short: `head`, `grep -n`, `pytest -q`.\n- If an edit fails twice, reread the exact lines and retry with a smaller snippet. Keep each edit small so the tool call is not cut off.\n",
 "prompts/CREDIT.txt": "Config A (baseline) is the public walkthrough agent 'Version 2' by Kaggle user zhukovoleksiy,\n'Gemma 4 | Walkthrough & First Submission' (scored 0.10 on public LB), reused with attribution per\ncompetition public-sharing rules. Source: https://www.kaggle.com/code/zhukovoleksiy/gemma-4-walkthrough-first-submission\n",
 "prompts/analyzer.md": "You are `code_analyzer`, a read-only code navigator. You never modify files. Given an issue, find exactly where it must be fixed.\n\n## Tools\n- `run_command` for read-only commands only: `git grep -n`, `grep -rn`, `sed -n 'START,ENDp' FILE`, `ls`, `git log -p -S \"<text>\"`. ripgrep (rg) is not installed.\n- `read_file` with tight line ranges to confirm what you found.\n- `get_code_neighbors` and `get_code_subgraph` for synchronous call relationships. The graph has only \"calls\" edges and no async functions.\n- `search_similar_code` takes a symbol name such as `APIKeyHeader` or `routing.get_request_handler`, not a sentence, and its ranking is imprecise. Confirm every hit by reading the code.\n- If a graph tool returns an error, stop using it and search the source instead.\n\n## Method\n1. Pull the identifiers out of the issue: function and class names, error messages, file paths, options. Pull-request descriptions may include template text; ignore it.\n2. Search for each one, then follow the code until you reach the line where the behaviour diverges from what the issue expects.\n3. Confirm by reading the code. Never guess line numbers.\n\n## Answer (at most 250 words, nothing else)\nLOCATION: <path>:<start>-<end> (<function or class>)\nROOT CAUSE: <one or two sentences>\nFIX PLAN: <the concrete change>\nRELATED: <other places needing the same change, or \"none\">\nTESTS: <existing test files that exercise this code>\nCONFIDENCE: high | medium | low\n",
 "skills/localize/SKILL.md": "---\nname: localize\ndescription: BM25 localizer over /workspace source; returns top-k candidate files and functions with line ranges. Use before reading files when the statement does not name the file.\n---\n\n# Skill: localize\n\nFind the files and functions most likely to contain the bug/feature described in the task, using a\nfast BM25 search over the repository source. Use this **first**, before reading files or calling the\ngraph tools, whenever the problem statement does not already name the exact file to edit.\n\n## When to use\n- The statement describes a symptom but not a file path (the common case).\n- You are unsure which file/function to open first.\n- Do NOT use it to read file contents \u2014 it returns a ranked shortlist, then you `read_file` the top hits.\n\n## How to run (works offline in the sandbox)\nThe script is pure standard-library Python. Write it to /tmp and run it so it never pollutes your patch:\n\n    write_file(\"/tmp/localize.py\", <contents of localize.py>)   # once\n    run_command(\"python3 /tmp/localize.py --root /workspace --k 10 \\\"<the problem statement>\\\"\")\n\nOr, if the statement is long, put it in a file first:\n\n    write_file(\"/tmp/ps.txt\", \"<the problem statement>\")\n    run_command(\"python3 /tmp/localize.py --root /workspace --k 10 --statement-file /tmp/ps.txt\")\n\n## What it returns (compact, safe for the 32k context)\n- `top candidate files` \u2014 ranked list of file paths.\n- `top candidate functions/classes` \u2014 `file:line_start-line_end  symbol  (score)`.\n\nIt excludes test files and configs from the candidates (you must not edit tests anyway).\n\n## How to act on it\n1. `read_file` the top 1\u20133 functions (use the printed line ranges to read only the relevant span).\n2. If the top file looks right but the exact function is unclear, read the top 2\u20133 functions in that file.\n3. Make the minimal edit, add/keep a targeted test if needed, then `submit_patch`.\n\n## Notes\n- It ranks by lexical overlap (BM25); if the statement names a symbol, that symbol usually ranks near\n  the top. If results look off, add distinctive identifiers/error strings from the statement to the query.\n- It does not run the code and costs one `run_command` call (~1\u20132 s on these repos).\n",
 "skills/localize/scripts/localize.py": "\"\"\"localize.py \u2014 dependency-free BM25 localizer for the swegemma sandbox.\n\nRuns INSIDE the agent's /workspace container. Parses the repo's Python source into function/class\nunits (AST), builds BM25 over unit name+source, filters out test code, and prints the top-k\nfile:function candidates with line ranges. Pure standard library only (no pip, no /wheels needed) so it\nworks offline in the sandbox.\n\nUsage (the agent runs this via run_command, or writes it to /tmp and runs it):\n    python3 localize.py --root /workspace --k 10 \"PROBLEM STATEMENT TEXT\"\n    python3 localize.py --root /workspace --k 10 --statement-file /tmp/ps.txt\n\nOutput is compact (a ranked list, no source dumps) to stay within the 32k context budget.\n\"\"\"\nimport argparse\nimport ast\nimport io\nimport json\nimport math\nimport os\nimport re\nimport sys\nimport tokenize\n\nIDENT = re.compile(r\"[A-Za-z_][A-Za-z0-9_]{2,}\")\nSTOP = set(\"the and for with that this from are not was but you can use have when into then its will \"\n           \"has all should would could add fix use these those\".split())\nTEST_RE = re.compile(r\"(^|/)(tests?|testing)/|(^|/)test_[^/]*\\.py$|_test\\.py$\")\n\n\ndef tokens(text):\n    out = []\n    for w in IDENT.findall(text):\n        for p in re.split(r\"_|(?<=[a-z0-9])(?=[A-Z])\", w):\n            if len(p) > 1:\n                out.append(p.lower())\n        out.append(w.lower())\n    return [t for t in out if t not in STOP]\n\n\nclass BM25:\n    def __init__(self, corpus, k1=1.5, b=0.75):\n        self.k1, self.b, self.docs = k1, b, corpus\n        self.dl = [len(d) for d in corpus]\n        self.avgdl = (sum(self.dl) / len(corpus)) if corpus else 0.0\n        self.f, df = [], {}\n        for d in corpus:\n            tf = {}\n            for w in d:\n                tf[w] = tf.get(w, 0) + 1\n            self.f.append(tf)\n            for w in tf:\n                df[w] = df.get(w, 0) + 1\n        N = len(corpus)\n        self.idf = {w: max(1e-6, math.log((N - n + 0.5) / (n + 0.5) + 1)) for w, n in df.items()}\n\n    def scores(self, query):\n        q = [w for w in query if w in self.idf]\n        out = []\n        for i, tf in enumerate(self.f):\n            s, dl = 0.0, self.dl[i]\n            for w in q:\n                if w in tf:\n                    fr = tf[w]\n                    s += self.idf[w] * fr * (self.k1 + 1) / (fr + self.k1 * (1 - self.b + self.b * dl / self.avgdl))\n            out.append(s)\n        return out\n\n\ndef module_name(rel_path):\n    p = re.sub(r\"^(src|docs_src)/\", \"\", rel_path)\n    p = p[:-3] if p.endswith(\".py\") else p\n    return p.replace(\"/\", \".\").rstrip(\".\").removesuffix(\".__init__\")\n\n\ndef iter_units(root):\n    \"\"\"Yield (name, text, rel_path, lineno, end_lineno) for each function/class in the repo's .py files.\"\"\"\n    for dirpath, dirs, files in os.walk(root):\n        dirs[:] = [d for d in dirs if d not in (\".git\", \"__pycache__\", \".pytest_cache\")]\n        for fn in files:\n            if not fn.endswith(\".py\"):\n                continue\n            full = os.path.join(dirpath, fn)\n            rel = os.path.relpath(full, root)\n            if TEST_RE.search(\"/\" + rel.replace(os.sep, \"/\")):\n                continue\n            try:\n                src = open(full, encoding=\"utf-8\", errors=\"ignore\").read()\n                tree = ast.parse(src)\n            except Exception:\n                continue\n            lines = src.splitlines()\n            mod = module_name(rel.replace(os.sep, \"/\"))\n\n            def walk(node, prefix):\n                for child in ast.iter_child_nodes(node):\n                    if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n                        name = f\"{prefix}.{child.name}\" if prefix else child.name\n                        lo = child.lineno\n                        hi = getattr(child, \"end_lineno\", lo)\n                        text = \"\\n\".join(lines[lo - 1:hi])\n                        yield (f\"{mod}.{name}\", text, rel.replace(os.sep, \"/\"), lo, hi)\n                        if isinstance(child, ast.ClassDef):\n                            yield from walk(child, name)\n            yield from walk(tree, \"\")\n\n\ndef build_call_graph(units):\n    \"\"\"Lightweight undirected call graph from source: edge between unit i and j if j's short name is\n    referenced as an identifier in i's body (or vice versa). Approximates the shipped `calls` graph.\"\"\"\n    short = [u[0].split(\".\")[-1] for u in units]\n    short_to_idx = {}\n    for i, s in enumerate(short):\n        short_to_idx.setdefault(s, []).append(i)\n    adj = [set() for _ in units]\n    for i, (_, text, *_ ) in enumerate(units):\n        refs = set(IDENT.findall(text or \"\"))\n        for r in refs:\n            for j in short_to_idx.get(r, ()):\n                if j != i:\n                    adj[i].add(j); adj[j].add(i)\n    return adj\n\n\ndef personalized_pagerank(adj, restart, alpha=0.5, iters=40):\n    n = len(adj)\n    deg = [len(a) or 1 for a in adj]\n    p = [max(x, 0.0) for x in restart]\n    s = sum(p) or 1.0\n    p = [x / s for x in p]\n    r = p[:]\n    for _ in range(iters):\n        nxt = [(1 - alpha) * p[i] for i in range(n)]\n        for i in range(n):\n            share = alpha * r[i] / deg[i]\n            for j in adj[i]:\n                nxt[j] += share\n        r = nxt\n    return r\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"statement\", nargs=\"?\", default=\"\")\n    ap.add_argument(\"--root\", default=\"/workspace\")\n    ap.add_argument(\"--k\", type=int, default=10)\n    ap.add_argument(\"--statement-file\")\n    ap.add_argument(\"--json\", action=\"store_true\")\n    ap.add_argument(\"--ppr\", action=\"store_true\",\n                    help=\"re-rank FILES by BM25-seeded personalized PageRank over a source call-graph (C2 recipe)\")\n    ap.add_argument(\"--alpha\", type=float, default=0.5)\n    a = ap.parse_args()\n    ps = open(a.statement_file).read() if a.statement_file else a.statement\n    if not ps.strip():\n        print(\"localize: empty statement\", file=sys.stderr)\n        sys.exit(2)\n\n    units = list(iter_units(a.root))\n    if not units:\n        print(\"localize: no python units found under\", a.root, file=sys.stderr)\n        sys.exit(1)\n    names = [u[0] for u in units]\n    bm = BM25([tokens(n + \" \" + t) for n, t, *_ in units])\n    sc = bm.scores(tokens(ps))\n    ppr = None\n    if a.ppr:\n        adj = build_call_graph(units)\n        ppr = personalized_pagerank(adj, sc, alpha=a.alpha)\n    order = sorted(range(len(units)), key=lambda i: -sc[i])\n\n    # file ranking = best (PPR if --ppr, else BM25) unit score per file\n    fscore_src = ppr if ppr is not None else sc\n    file_best = {}\n    for i in range(len(units)):\n        rel = units[i][2]\n        if rel not in file_best or fscore_src[i] > file_best[rel]:\n            file_best[rel] = fscore_src[i]\n    top_files = sorted(file_best, key=lambda f: -file_best[f])[:a.k]\n\n    if a.json:\n        print(json.dumps({\n            \"top_files\": top_files[:a.k],\n            \"top_functions\": [{\"name\": names[i], \"file\": units[i][2],\n                               \"lines\": [units[i][3], units[i][4]], \"score\": round(sc[i], 3)}\n                              for i in order[:a.k]],\n        }, indent=1))\n        return\n    print(f\"# localize: top {a.k} candidate files\")\n    for f in top_files:\n        print(f\"  {f}\")\n    print(f\"\\n# top {a.k} candidate functions/classes (file:lines  symbol)\")\n    for i in order[:a.k]:\n        n, _, rel, lo, hi = units[i]\n        print(f\"  {rel}:{lo}-{hi}  {n.split('.')[-1]}   (score {sc[i]:.2f})\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
 "sub_agents/code_analyzer.yaml": "name: code_analyzer\nmodel: gemma-4-31b-it-qat-w4a16-ct\ndescription: Read-only code navigator. Given an issue, returns where to fix it, the root cause and a fix plan.\ninstruction: !include ../prompts/analyzer.md\ntools:\n  - run_command\n  - read_file\n  - get_code_neighbors\n  - get_code_subgraph\n  - search_similar_code\ngenerate_content_config: !include ../configs/sampling.yaml\n"
}

WORKING = Path("/kaggle/working")
BUNDLE = WORKING / "bundle"
shutil.rmtree(BUNDLE, ignore_errors=True)
for rel, text in FILES.items():
    p = BUNDLE / rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(text)

ROOT_CONFIGS = ["agent.yaml","agent.yml","root_agent.yaml","root_agent.yml"]
ALLOWED = {".yaml",".yml",".md",".txt",".py",".json",".safetensors"}
yaml.SafeLoader.add_constructor("!include", lambda l,n: l.construct_scalar(n))
files=[p for p in BUNDLE.rglob("*") if p.is_file()]
roots=[n for n in ROOT_CONFIGS if (BUNDLE/n).is_file()]
assert len(roots)==1, roots
assert not any(p.is_symlink() for p in BUNDLE.rglob("*"))
bad=[p.name for p in files if p.suffix not in ALLOWED]; assert not bad, bad
assert sum(p.stat().st_size for p in files) < 3*2**30
models=set()
for c in (p for p in files if p.suffix in (".yaml",".yml")):
    t=c.read_text(); d=yaml.safe_load(t) or {}
    for inc in re.findall(r"!include\s+(\S+)", t):
        assert (c.parent/inc).is_file(), f"{c.name}: missing include {inc}"
    if "model" in d: models.add(d["model"])
assert models == {"gemma-4-31b-it-qat-w4a16-ct"}, models
assert (BUNDLE/"skills/localize/scripts/localize.py").is_file()
assert "--ppr" in (BUNDLE/"prompts/system.md").read_text(), "C2 prompt must use --ppr"
print("VALIDATION OK:", roots[0], len(files), "files, model", models)

ZIP = WORKING / "submission.zip"
if ZIP.exists(): ZIP.unlink()
with zipfile.ZipFile(ZIP,"w",zipfile.ZIP_DEFLATED) as z:
    for p in files: z.write(p, p.relative_to(BUNDLE))
print("wrote", ZIP, ZIP.stat().st_size, "bytes")
with zipfile.ZipFile(ZIP) as z: print("contents:", z.namelist())
